-- --- 174..184: ENTRENAMIENTOS Y PROTOCOLOS DE CARRERA 5K / 10K / VELOCIDAD / PIRAMIDE / FARTLEK ---
(174, NULL, 'Series Pirámide Pista (400m-500m-600m-800m-600m-500m-400m)', 'carrera', 'piramide_pista', 'carrera', 0, 2, 1, 'pista atletismo o llano', '1 a 3 bloques de pirámide (400m - 500m - 600m - 800m - 600m - 500m - 400m = 3.800m/bloque) en Zona 4-5 (ritmo 5K-10K). Descanso activo de 90-120s andando entre series y 3-4 min entre bloques.', NULL, NULL, 'ninguno', 0),
(175, NULL, 'Fartlek 5K/10K: 5 min Zona 4 + 1:30 min Zona 2 (andando o trote)', 'carrera', 'fartlek_umbral', 'carrera', 0, 2, 1, 'asfalto o parque', '4 a 6 bloques alternando 5 minutos corriendo fuerte en Zona 4 (ritmo umbral / 10K) con 1:30 min de recuperación activa andando o trotando suave en Zona 2.', NULL, NULL, 'ninguno', 0),
(176, NULL, 'Fartlek Corto Reactivo: 8× (2 min Zona 4-5 + 1 min Zona 2)', 'carrera', 'fartlek_corto', 'carrera', 0, 2, 1, 'asfalto o tierra', '8 a 10 cambios de ritmo de 2 minutos vivos en Zona 4-5 (ritmo 5K) seguidos de 1 minuto de trote suave o caminata ligera en Zona 2.', NULL, NULL, 'ninguno', 0),
(177, NULL, 'Fartlek Piramidal por Tiempo (1-2-3-4-3-2-1 min Zona 4)', 'carrera', 'fartlek_piramide', 'carrera', 0, 2, 1, 'asfalto o parque', 'Pirámide por tiempo en Zona 4: 1 min - 2 min - 3 min - 4 min - 3 min - 2 min - 1 min fuerte, recuperando la mitad del tiempo de cada tramo al trote suave en Zona 2.', NULL, NULL, 'ninguno', 0),
(178, NULL, 'Series de Velocidad 8×200m (Ritmo 1500m/3K · Zona 5)', 'carrera', 'intervalos_velocidad', 'carrera', 0, 2, 1, 'pista atletismo', '8 a 10 repeticiones de 200m rápidas y fluidas con reactividad de tobillo y cadencia alta. Recuperación activa de 90s andando o trotando muy suave.', NULL, NULL, 'ninguno', 0),
(179, NULL, 'Series Rápidas 8×300m en Pista (Potencia y Economía)', 'carrera', 'intervalos_velocidad', 'carrera', 0, 2, 1, 'pista atletismo', '8 repeticiones de 300m en Zona 5 mejorando potencia aeróbica y zancada reactiva sin crispar hombros. Descanso activo de 90-105s andando.', NULL, NULL, 'ninguno', 0),
(180, NULL, 'Series de 6×500m a Ritmo 5K (Zona 4-5)', 'carrera', 'intervalos_medios', 'carrera', 0, 2, 1, 'pista o recta llana', '6 a 8 repeticiones de 500m a ritmo objetivo de 5K (Zona 4 alta / Zona 5) con descanso activo de 90-120s andando.', NULL, NULL, 'ninguno', 0),
(181, NULL, 'Series de 5×800m para 5K/10K (VO2max · Zona 4-5)', 'carrera', 'intervalos_vo2max', 'carrera', 0, 2, 1, 'pista atletismo', '5 a 6 repeticiones de 800m (2 vueltas a pista) a ritmo de 5K sostenido con recuperación activa de 105-120s andando entre series.', NULL, NULL, 'ninguno', 0),
(182, NULL, 'Escalera Descendente Pista (1000m - 800m - 600m - 400m - 200m)', 'carrera', 'escalera_pista', 'carrera', 0, 2, 1, 'pista atletismo', '1 a 2 bloques descendentes aumentando un punto la velocidad en cada escalón (de Zona 4 en el 1000m a Zona 5 alta en el 200m) con 90-120s de recuperación andando.', NULL, NULL, 'ninguno', 0),
(183, NULL, 'Series Mixtas 4×1200m a Ritmo 10K (Zona 4)', 'carrera', 'intervalos_largos', 'carrera', 0, 2, 1, 'pista o asfalto medido', '4 repeticiones de 1200m (3 vueltas a pista) a ritmo controlado de 10K (Zona 4) con 2 minutos de recuperación activa.', NULL, NULL, 'ninguno', 0),
(184, NULL, 'Series Umbral 3×1500m (Especificidad 5K/10K · Zona 4)', 'carrera', 'intervalos_umbral', 'carrera', 0, 2, 1, 'pista o circuito llano', '3 a 4 repeticiones de 1500m sosteniendo ritmo de umbral anaeróbico (Zona 4) con 90-120s de descanso activo.', NULL, NULL, 'ninguno', 0)
